/** How a PR's checks stand, folded from its status check rollup. */
export type Checks = 'none' | 'pending' | 'passing' | 'failing'

/** A check that failed: a check run or a commit status. */
export type FailedCheck = {
  name: string
  /** The GitHub Actions run of a check run, whose log gh fetches; '' for a commit status or another app's check. */
  runId: string
}

export type PullRequest = {
  number: number
  title: string
  author: string
  isDraft: boolean
  /** `APPROVED`, `CHANGES_REQUESTED`, `REVIEW_REQUIRED`, or '' when GitHub gives none. */
  review: string
  checks: Checks
  /** The checks that failed; empty unless `checks` is `failing`. */
  failed: FailedCheck[]
  /** The PR's head branch. */
  branch: string
}

/** Where the current branch's PR's checks stood at the last poll, to tell when they turn. */
export type Watch = {
  branch: string
  /** The PR whose head branch is `branch`; 0 when it has none. */
  number: number
  checks: Checks
}

/** An open issue that blocks another, as GitHub's issue dependencies record it. */
export type Blocker = {
  number: number
  title: string
}

export type Issue = {
  number: number
  title: string
  /** The issue's page on GitHub; '' when gh gives none. */
  url: string
  author: string
  labels: string[]
  /** The open issues this one is blocked by; empty when nothing open blocks it. */
  blockedBy: Blocker[]
}

/** A sub-issue of the pinned issue: a ticket on a wayfinder map. */
export type SubIssue = {
  number: number
  title: string
  /** The ticket's page on GitHub; '' when GitHub gives none. */
  url: string
  isOpen: boolean
  /** Whether anyone is assigned: a claimed ticket. */
  isAssigned: boolean
  labels: string[]
  /** Whether any issue it is blocked by is still open. */
  isBlocked: boolean
}

/** The issue a /wayfinder run works on, as the last load read it. */
export type Pin = {
  number: number
  title: string
  /** The issue's page on GitHub; '' when GitHub gives none. */
  url: string
  isOpen: boolean
  /** Its first 100 sub-issues, in the order GitHub keeps them on the issue. */
  subIssues: SubIssue[]
}

export type GitHubView = {
  status: 'idle' | 'loading' | 'error' | 'unavailable'
  /** `owner/name` of the repo listed; '' before the first load. */
  repo: string
  /** The branch the session's folder is on; '' before the first load and on a detached HEAD. */
  branch: string
  prs: PullRequest[]
  issues: Issue[]
  /** The pinned issue of `repo` as the last load read it; null with no pin, or with pinning off. */
  pin: Pin | null
  /** Why the lists could not load (status `error` or `unavailable`). */
  error: string
  /** Milliseconds since the epoch of the last successful load; 0 before it. */
  updatedAt: number
  /** Bumped by each load; a load whose id is no longer current is dropped. */
  runId: number
}

declare module 'claude-code' {
  interface PluginState {
    'github-panel': {
      view: GitHubView
      /** True once this session's start-up load has run: at start, or at the first attach. */
      hasStartedUp: boolean
      /** The current branch's PR's checks as the last load found them; null before the first load. */
      watched: Watch | null
    }
  }
}
